import test from 'node:test';
import assert from 'node:assert/strict';
import { createGame, createRunState, getCourse, stepRun } from '../src/games/wallrunner-relay.js';
import { harness, input, mockContext, seeded } from './harness.js';

// Legal public-input routes generated by a simple human-style policy (hold Right and X, tap Space
// just before roof edges, one canyon kick) at 1/30 s decisions. Each token is
// direction (L, N, R), wall-run held (0/1), Space pressed this tick (0/1).
const ROUTES = [
  'R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R11 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R11 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R11 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R11 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R11 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R00 R00 R00 R00 R00 R00 R00 R00 R00 R00 R00 R00 R00 R00 R00',
  'L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 R11 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R11 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R11 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R11 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R00 R00 R00 R00 R00 R00 R00 R00 R00 R00 R00 R00 R00 R00 R00',
  'L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 L10 R11 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R11 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R11 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R11 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R10 R00 R00 R00 R00 R00 R00 R00 R00 R00 R00 R00 R00 R00 R00 R00',
];
const SETTLE_TICKS = 150; // stand on the starting relay pad for five seconds
const idle = Array.from({ length: SETTLE_TICKS }, () => 'N00');
const tokens = (route) => route.split(' ');
const toInput = (token) =>
  input(
    [
      token[0] === 'L' ? 'ArrowLeft' : token[0] === 'R' ? 'ArrowRight' : '',
      token[1] === '1' ? 'KeyX' : '',
    ],
    token[2] === '1' ? ['Space'] : [],
  );
const heldOnly = (token, first) => {
  const base = toInput(token);
  const held = ['ArrowLeft', 'ArrowRight', 'KeyX'].filter((c) => base.held(c));
  return input(held, first && token[2] === '1' ? ['Space'] : []);
};
function play(game, list, hz) {
  const course = game.getState().course;
  for (const token of list)
    for (let f = 0; f < hz / 30; f++) {
      game.update(1 / hz, heldOnly(token, f === 0));
      const s = game.getState();
      if (s.course !== course || s.phase !== 'playing') return;
    }
}

test('wallrunner quality: each course is individually winnable with legal input at 30/60/120 Hz', () => {
  for (const hz of [30, 60, 120]) {
    ROUTES.forEach((route, i) => {
      const s = createRunState(i + 1),
        frames = hz / 30;
      for (const token of tokens(route))
        for (let f = 0; f < frames; f++) stepRun(s, 1 / hz, heldOnly(token, f === 0));
      assert.equal(s.lives, 4, `course ${i + 1} @${hz} lost a life`);
      assert.ok(s.course > i + 1 || s.phase === 'won', `course ${i + 1} @${hz}`);
    });
  }
});

test('wallrunner quality: full three-course campaign reaches victory once at 30/60/120 Hz', () => {
  const finals = [];
  for (const hz of [30, 60, 120]) {
    const h = harness(),
      g = createGame(h.env);
    ROUTES.forEach((route, i) => {
      play(g, tokens(route), hz);
      if (i < 2) {
        assert.equal(g.getState().course, i + 2, `course ${i + 1} @${hz}`);
        assert.ok(g.getState().banner > 0);
        play(g, idle, hz);
        assert.ok(g.getState().energy > 99);
      }
    });
    const s = g.getState();
    assert.equal(s.phase, 'won', `hz ${hz}`);
    assert.equal(s.lives, 4);
    assert.equal(s.courseTimes.length, 3);
    assert.equal(h.ends.length, 1);
    assert.equal(h.ends[0].won, true);
    assert.equal(h.ends[0].score, s.score);
    assert.match(h.ends[0].message, /relay is complete/);
    assert.ok(s.kicks >= 2);
    assert.ok(s.spent.run > 10);
    const before = structuredClone(s);
    g.update(1 / 30, heldOnly('R11', true));
    assert.deepEqual(g.getState(), before);
    finals.push(s);
  }
  for (const f of finals.slice(1)) {
    assert.ok(Math.abs(f.score - finals[0].score) <= 8);
    assert.deepEqual(f.courseTimes.length, 3);
  }
});

test('wallrunner quality: results agree between frame rates', () => {
  const states = [30, 60, 120].map((hz) => {
    const s = createRunState(2);
    for (const token of tokens(ROUTES[1]).slice(0, 120))
      for (let f = 0; f < hz / 30; f++) stepRun(s, 1 / hz, heldOnly(token, f === 0));
    return s;
  });
  for (const s of states.slice(1)) {
    assert.ok(Math.abs(s.player.x - states[0].player.x) < 1e-6);
    assert.ok(Math.abs(s.player.y - states[0].player.y) < 1e-6);
    assert.ok(Math.abs(s.energy - states[0].energy) < 1e-6);
  }
});

test('wallrunner quality: campaign frames draw on every course and the won frame', () => {
  const sizes = [],
    ctx = new Proxy(mockContext(), {
      set(t, p, v) {
        if (p === 'font') sizes.push(Number(/(\d+)px/.exec(v)[1]));
        t[p] = v;
        return true;
      },
    });
  for (const lang of ['en', 'zh']) {
    const g = createGame(harness({ lang }).env);
    for (let i = 0; i < 3; i++) {
      const route = tokens(ROUTES[i]);
      play(g, route.slice(0, 15), 60);
      g.draw(ctx);
      play(g, route.slice(15), 60);
      g.draw(ctx);
      if (i < 2) play(g, idle, 60);
    }
    assert.equal(g.getState().phase, 'won');
    g.draw(ctx);
  }
  assert.ok(sizes.every((n) => n >= 14 && n <= 16));
});

test('wallrunner quality: authored courses are distinct and every pad, goal and chalk mark is on the geometry', () => {
  const sigs = new Set();
  for (let c = 1; c <= 3; c++) {
    const course = getCourse(c);
    sigs.add(JSON.stringify(course.solids.map((o) => [o.x, o.y, o.w, o.chalk, o.slick])));
    assert.ok(course.name.en && course.name.zh);
    let chalkFaces = 0;
    for (const o of course.solids) {
      for (const side of ['L', 'R'])
        for (const [y0, y1] of [...o.chalk[side], ...o.slick[side]]) {
          chalkFaces++;
          assert.ok(y0 < y1 && y1 <= o.y + o.h && y1 > o.y, 'mark lies on exposed face');
        }
      for (const [x0, x1] of o.pads) assert.ok(x0 >= o.x && x1 <= o.x + o.w);
    }
    assert.ok(chalkFaces >= 2);
    assert.ok(course.goal.x < course.width);
  }
  assert.equal(sigs.size, 3);
  assert.ok(
    getCourse(2).solids.some((o) => o.chalk.R.length) &&
      getCourse(3).solids.some((o) => o.slick.L.length),
  );
});

function overlaps(p, o) {
  return (
    p.x + p.w > o.x + 1e-3 &&
    p.x < o.x + o.w - 1e-3 &&
    p.y + p.h > o.y + 1e-3 &&
    p.y < o.y + o.h - 1e-3
  );
}
function randomInput(random) {
  const held = [];
  const r = random();
  if (r < 0.3) held.push('ArrowLeft');
  else if (r < 0.7) held.push('ArrowRight');
  if (random() < 0.5) held.push('KeyX');
  return input(held, random() < 0.08 ? ['Space'] : []);
}

test('wallrunner quality: seeded random play stays finite, bounded and outside every solid', () => {
  for (const seed of [1, 7, 23, 99]) {
    for (const course of [1, 2, 3]) {
      const random = seeded(seed * 31 + course),
        s = createRunState(course);
      let last = s.energy,
        lastRefilled = 0;
      for (let n = 0; n < 6000 && s.phase === 'playing'; n++) {
        stepRun(s, 1 / 60, randomInput(random));
        const p = s.player,
          solids = getCourse(s.course).solids;
        for (const v of [p.x, p.y, p.vx, p.vy, s.energy, s.camera.x, s.camera.y, s.time])
          assert.ok(Number.isFinite(v));
        assert.ok(s.energy >= 0 && s.energy <= 100);
        assert.ok(Math.abs(p.vx) <= 160 && Math.abs(p.vy) <= 540);
        assert.ok(s.trail.length <= 40);
        assert.ok(
          (p.y - s.camera.y) * 2 >= 55.9 && (p.y + p.h - s.camera.y) * 2 <= 276.1,
          'runner on screen',
        );
        for (const o of solids) assert.ok(!overlaps(p, o), `seed ${seed} c${course} tick ${n}`);
        // Energy only ever increases through the pad refill counter.
        if (s.energy > last + 1e-9) assert.ok(s.refilled > lastRefilled);
        last = s.energy;
        lastRefilled = s.refilled;
      }
      const identity = 100 - s.spent.run - s.spent.kick + s.refilled;
      assert.ok(Math.abs(identity - s.energy) < 1e-6, `accounting ${identity} vs ${s.energy}`);
    }
  }
});

function maxAscent(s, policy, seconds) {
  const start = s.player.y + s.player.h;
  let best = 0,
    base = start;
  for (let n = 0; n < seconds * 120 && s.phase === 'playing'; n++) {
    const lives = s.lives;
    stepRun(s, 1 / 120, policy(s, n));
    if (s.lives < lives) base = s.player.y + s.player.h;
    best = Math.max(best, base - (s.player.y + s.player.h));
  }
  return best;
}

test('wallrunner quality: kick and detach loops cannot create unlimited height', () => {
  // Facing canyon walls with the most aggressive kick policy possible.
  const kickLoop = (s) => {
    const dir = s.player.vx > 0 ? ['ArrowRight'] : s.player.vx < 0 ? ['ArrowLeft'] : ['ArrowRight'];
    return input(dir, ['Space']);
  };
  const s = createRunState(2);
  // Climb off the pad quickly so refills cannot feed the loop.
  const gain = maxAscent(s, kickLoop, 40);
  assert.ok(s.spent.kick <= 100 + s.refilled + 1e-9, 'kicks are paid for by energy');
  assert.ok(s.kicks * 10 === s.spent.kick);
  assert.ok(gain <= s.kicks * 50 + 70, `gain ${gain}`);
  assert.ok(gain < 600);
  // A wall-run toggling loop on a single chalk face only decays momentum.
  const wall = createRunState();
  Object.assign(wall.player, { x: 390, y: 200, ground: false, approach: 110, approachTimer: 0.18 });
  let momentum = 0,
    rises = 0,
    previous = 0;
  const top = wall.player.y;
  let highest = top;
  for (let n = 0; n < 2400 && wall.phase === 'playing'; n++) {
    stepRun(wall, 1 / 120, input(['ArrowRight', ...(n % 20 < 10 ? ['KeyX'] : [])]));
    if (wall.player.ground) break;
    if (wall.player.momentum > previous + 1e-9) {
      rises++;
      momentum = Math.max(momentum, wall.player.momentum);
    }
    previous = wall.player.momentum;
    highest = Math.min(highest, wall.player.y);
  }
  assert.ok(rises <= 1, `momentum regained ${rises}`);
  assert.ok(top - highest <= 290);
});

test('wallrunner quality: toggling wall-run in the air cannot refresh momentum before touching down', () => {
  const s = createRunState();
  Object.assign(s.player, { x: 390, y: 200, ground: false, approach: 110, approachTimer: 0.18 });
  const seen = [];
  for (let n = 0; n < 1200 && !s.player.ground && s.phase === 'playing'; n++) {
    stepRun(s, 1 / 120, input(n % 40 < 20 ? ['ArrowRight', 'KeyX'] : ['ArrowLeft']));
    seen.push(s.player.momentum);
  }
  for (let i = 1; i < seen.length; i++)
    if (seen[i] > seen[i - 1] + 1e-9) assert.ok(seen[i - 1] === 0 || i < 5);
});

test('wallrunner quality: an exhausted runner can still recover on a pad and continue the course', () => {
  const g = createGame(harness().env);
  // Drain energy through a wall-run, collapse, then recover at the pad.
  const s = createRunState();
  s.energy = 0.5;
  Object.assign(s.player, { x: 390, y: 200, ground: false });
  for (let n = 0; n < 240 && s.lives === 4; n++) stepRun(s, 1 / 60, input(['ArrowRight', 'KeyX']));
  assert.equal(s.lives, 3);
  for (let n = 0; n < 300; n++) stepRun(s, 1 / 60, input());
  assert.equal(s.energy, 100);
  for (const token of tokens(ROUTES[0]))
    for (let f = 0; f < 2; f++) stepRun(s, 1 / 60, heldOnly(token, f === 0));
  assert.equal(s.course, 2);
  assert.ok(g.getState().lives === 4);
});

// Shifts every direction change, wall-run change and Space press of a route by up to +/-amp ticks.
function perturb(route, amp, random) {
  const list = route.split(' '),
    n = list.length,
    shift = () => Math.round((random() * 2 - 1) * amp);
  const channel = (values) => {
    const events = [[0, values[0]]];
    for (let i = 1; i < n; i++) if (values[i] !== values[i - 1]) events.push([i, values[i]]);
    const moved = events
      .slice(1)
      .map(([i, v]) => [Math.max(0, i + shift()), v])
      .sort((a, b) => a[0] - b[0]);
    let cursor = 0,
      current = values[0];
    return values.map((_, i) => {
      while (cursor < moved.length && moved[cursor][0] <= i) current = moved[cursor++][1];
      return current;
    });
  };
  const dir = channel(list.map((k) => 'LNR'.indexOf(k[0])));
  const wall = channel(list.map((k) => k[1]));
  const space = new Array(n).fill('0');
  list.forEach((k, i) => {
    if (k[2] === '1') space[Math.min(n - 1, Math.max(0, i + shift()))] = '1';
  });
  return list.map((_, i) => `${'LNR'[dir[i]]}${wall[i]}${space[i]}`).join(' ');
}

test('wallrunner quality: routes tolerate human timing jitter of +/-1 and +/-2 ticks at 30/60/120 Hz', () => {
  const TRIALS = 50;
  for (const hz of [30, 60, 120]) {
    ROUTES.forEach((route, i) => {
      for (const amp of [1, 2]) {
        const random = seeded(1000 * (i + 1) + amp * 10 + hz);
        let wins = 0;
        for (let n = 0; n < TRIALS; n++) {
          const s = createRunState(i + 1);
          for (const token of tokens(perturb(route, amp, random)))
            for (let f = 0; f < hz / 30; f++) stepRun(s, 1 / hz, heldOnly(token, f === 0));
          if (s.course > i + 1 || s.phase === 'won') wins++;
        }
        assert.ok(wins >= TRIALS * 0.9, `course ${i + 1} amp ${amp} @${hz}: ${wins}/${TRIALS}`);
      }
    });
  }
});

test('wallrunner quality: the canyon kick window is wide and a wall kick has a short contact grace', () => {
  const wins = [];
  for (let course = 2; course <= 3; course++) {
    for (let T = 10; T < 45; T++) {
      const s = createRunState(course);
      const list = [...Array(T).fill('L10'), 'R11', ...Array(60).fill('R10')];
      for (const token of list) stepRun(s, 1 / 30, heldOnly(token, true));
      if (s.player.ground && s.player.y + s.player.h <= 60 && s.lives === 4)
        wins.push(`${course}:${T}`);
    }
  }
  const per = (c) => wins.filter((w) => w.startsWith(`${c}:`)).length;
  assert.ok(per(2) >= 10 && per(3) >= 10, wins.join());
  // Contact grace: a kick pressed shortly after leaving the wall still works, once.
  const s = createRunState(2);
  Object.assign(s.player, {
    x: 100,
    y: 150,
    ground: false,
    graceTime: 0.1,
    graceFace: '1R',
    graceSide: -1,
  });
  Object.assign(s.player, { x: 108 });
  stepRun(s, 1 / 120, input([], ['Space']));
  assert.equal(s.kicks, 1);
  stepRun(s, 1 / 120, input([], ['Space']));
  assert.equal(s.kicks, 1);
});

test('wallrunner quality: any single input boundary shifted by up to two ticks still wins', () => {
  for (const hz of [30, 60]) {
    ROUTES.forEach((route, i) => {
      let count = 0;
      perturb(route, 2, () => (count++, 0.5));
      let runs = 0,
        wins = 0;
      for (let k = 0; k < count; k++)
        for (const delta of [-2, -1, 1, 2]) {
          let call = 0;
          const shifted = perturb(route, 2, () => (call++ === k ? (delta / 2 + 1) / 2 : 0.5));
          const s = createRunState(i + 1);
          for (const token of tokens(shifted))
            for (let f = 0; f < hz / 30; f++) stepRun(s, 1 / hz, heldOnly(token, f === 0));
          runs++;
          if (s.course > i + 1 || s.phase === 'won') wins++;
        }
      assert.ok(wins >= runs * 0.98, `course ${i + 1} @${hz}: ${wins}/${runs}`);
    });
  }
});

test('wallrunner quality: the runner and goal stay visible below the HUD during legal play', () => {
  ROUTES.forEach((route, i) => {
    const s = createRunState(i + 1);
    for (const token of tokens(route)) {
      for (let f = 0; f < 4; f++) stepRun(s, 1 / 120, heldOnly(token, f === 0));
      if (s.course !== i + 1) break;
      const p = s.player,
        head = (p.y - s.camera.y) * 2,
        feet = (p.y + p.h - s.camera.y) * 2;
      assert.ok(head >= 56 && feet <= 280, `course ${i + 1} head ${head} feet ${feet}`);
      const goal = getCourse(i + 1).goal;
      if (Math.abs(p.x - goal.x) < 100 && Math.abs(p.y + p.h - (goal.y + goal.h)) < 60)
        assert.ok(
          (goal.y - s.camera.y) * 2 >= 44 && (goal.y + goal.h - s.camera.y) * 2 <= 296,
          `goal visible on course ${i + 1}`,
        );
    }
  });
});

test('wallrunner quality: frame rate does not change when a life is lost', () => {
  // Walking off the first roof loses a life at the same simulated time regardless of frame length.
  const losses = [30, 60, 120].map((hz) => {
    const s = createRunState();
    for (let n = 0; n < hz * 12 && s.lives === 4; n++) stepRun(s, 1 / hz, input(['ArrowRight']));
    return s;
  });
  for (const s of losses) {
    assert.equal(s.lives, 3);
    assert.ok(Math.abs(s.time - losses[0].time) < 0.02, `time ${s.time}`);
  }
  const after = [30, 60, 120].map((hz) => {
    const s = createRunState();
    for (let n = 0; n < hz * 8; n++) stepRun(s, 1 / hz, input(['ArrowRight']));
    return s;
  });
  for (const s of after.slice(1)) {
    assert.ok(Math.abs(s.time - after[0].time) < 1e-9);
    assert.ok(Math.abs(s.player.x - after[0].player.x) < 1e-6);
    assert.equal(s.lives, after[0].lives);
  }
});
